callGraph.callee:
catalog
      .map((item) => {
        const values = quantities[item.name] || {};
        return {
          product_name: item.name,
          quantity: Number(values.quantity || 0),
          reserved_quantity: Number(values.reserved_quantity || 0),
        };
      })
      .filter

(reports || []).map(({ report }) => {
    const ing = report?.ingredient;
    if (!ing) return '';
    return `${ing.product_name}: ${formatQuantity(ing.quantity)} ${ing.unit}`.trim();
  }).filter
